"OLAYLAR_ORTACAG_IBERYA_MAGRIB:0846-01-01:0":{"b": ["Le forze aghlabidi sbarcarono a Ostia e saccheggiarono le basiliche di San Pietro e San Paolo a Roma.", "8ad8d42e"], "d": ["Le forze aghlabidi sbarcarono a Ostia e saccheggiarono le basiliche di San Pietro e San Paolo a Roma.", "8ad8d42e"]},
